-- ROUND ROBIN TABLE

CREATE table round_table
(
    Id INT,
    Name varchar(4000),
    Salary INT
)
WITH
(
    DISTRIBUTION = ROUND_ROBIN
);

SELECT * FROM round_table;

--REPLICATE TABLE

CREATE SCHEMA gold;

create table gold.dim_product
(
    dim_key_product INT,
    product_id INT,
    product_name varchar(4000)
)
WITH
(
    DISTRIBUTION = REPLICATE
);

--HASH TABLE

CREATE TABLE gold.fact_table
(
    dim_key_product INT,
    Revenue INT,
    Cost INT
)
WITH
(
    DISTRIBUTION = HASH(dim_key_product)
);
